if(new URLSearchParams(location.search).has("capture"))document.body.classList.add("recording-layout");
const requestedExample=new URLSearchParams(location.search).get('example');if(['observed','complete','missing'].includes(requestedExample))$('tesslExample').value=requestedExample;
for(const id of ['scenario','registry','short','pinned','tesslExample'])$(id).onchange=()=>{if(id==='scenario'){selected=0;expanded=false}if(id==='tesslExample'){const url=new URL(location);url.searchParams.set('example',$('tesslExample').value);history.replaceState(null,'',url)}render()};$('theme').onchange=()=>document.body.classList.toggle('light',$('theme').value==='light');$('reopen').onclick=()=>{closed=false;render()};document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('eval-guide').open)return;if(menuOpen){menuOpen=false;render();document.querySelector('[data-action="menu"]').focus()}else{closed=true;render()}e.preventDefault()}});document.addEventListener('click',e=>{if(menuOpen&&!e.target.closest('.menu')&&!e.target.closest('[data-action="menu"]')){menuOpen=false;render()}});
const picker=document.querySelector('.proto-picker'),highlight=picker.querySelector('.proto-picker-highlight'),items=[...picker.querySelectorAll('.proto-picker-item')];function moveHighlight(){const el=items[current];highlight.style.width=el.offsetWidth+'px';highlight.style.transform=`translateX(${el.offsetLeft}px)`}function setActive(i){if(i<0||i>2)return;current=i;items.forEach((el,j)=>{el.toggleAttribute('data-active',j===i);if(j===i)el.setAttribute('aria-current','true');else el.removeAttribute('aria-current')});moveHighlight();const url=new URL(location);url.searchParams.set('v',i+1);history.replaceState(null,'',url);render()}items.forEach((el,i)=>el.onclick=()=>setActive(i));window.addEventListener('resize',moveHighlight);document.addEventListener('keydown',e=>{if(/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName)||e.target.isContentEditable||e.target.closest('.grid,.menu')||e.metaKey||e.ctrlKey||e.altKey)return;const n=parseInt(e.key,10);if(n>=1&&n<=3)setActive(n-1);else if(e.key==='ArrowRight')setActive((current+1)%3);else if(e.key==='ArrowLeft')setActive((current+2)%3)});setActive(Math.max(0,Math.min(2,(parseInt(new URLSearchParams(location.search).get('v'),10)||1)-1)));requestAnimationFrame(()=>requestAnimationFrame(()=>picker.setAttribute('data-ready','')));setInterval(()=>{if(!menuOpen&&!refreshing&&!closed){const el=document.querySelector('.refresh span:last-child');if(el&&!refreshError)el.textContent='Preview refreshed '+age();const stamp=document.querySelector('.registry-age');if(stamp&&tesslExample()==='observed')stamp.textContent='v0.2.18 · saved observation'}},10000);
